// Newsletter sign-up → POST /v1/alexa/newsletter/subscribe (prayer-times-api
// src/routes/newsletter.js). Throws with a message for the person.
import apiConfig from '../config/apiConfig';

export async function subscribeToNewsletter(body, { rateMessage, errorMessage }) {
    const response = await fetch(`${apiConfig.baseUrl}/alexa/newsletter/subscribe`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
    });
    const json = await response.json().catch(() => null);
    if (response.status === 429) throw new Error(rateMessage);
    if (!response.ok) throw new Error(json?.error || errorMessage);
    return json?.data;
}
